map "https://fhir.hl7.at/elga/cda2fhir/r4/StructureMap/at-cda-eimpf-to-fhir-bundle" = "CdaEimpfToFhirBundle"

conceptmap "cda-eimpf-clinicaldocument-code-2-fhir-category" {
  prefix s = "http://loinc.org"

  s: "11369-6" == s: "11369-6"
}

uses "http://hl7.org/cda/stds/core/StructureDefinition/ClinicalDocument" alias CdaClinicalDocument as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/StructuredBody" alias CdaStructuredBody as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Section" alias CdaSection as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/SubstanceAdministration" alias CdaSubstanceAdministration as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Material" alias CdaMaterial as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Participant2" alias CdaParticipant2 as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Performer2" alias CdaPerformer2 as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Author" alias CdaAuthor as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Act" alias CdaAct as source

uses "http://hl7.org/fhir/4.3/StructureDefinition/Bundle" alias FhirBundle as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Composition" alias FhirComposition as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Patient" alias FhirPatient as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Immunization" alias FhirImmunization as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/ImmunizationRecommendation" alias FhirImmunizationRecommendation as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/CodeableConcept" alias FhirCodeableConcept as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Provenance" alias FhirProvenance as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/PractitionerRole" alias FhirPractitionerRole as target

imports "http://hl7.at/fhir/HL7ATCoreProfiles/4.0.1/StructureMap/at-cda-to-fhir-types"

// _________________________ Document Level Template  _________________________

group CdaEimpfToFhirBundle(source cda: CdaClinicalDocument, target fhir_patient: FhirPatient, target fhir_composition: FhirComposition, target fhir_bundle: FhirBundle) {
  cda ->
    // at least on Bundle level the profile is to be set
    fhir_bundle.meta as fhir_bundle_meta,
    fhir_bundle_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-bundle'
    then {
      // map the CDA header
      cda then CdaEimpfHeaderToFhirComposition(cda, fhir_composition, fhir_patient, fhir_bundle) "CdaEimpfHeaderToFhirComposition";
      cda then CdaEimpfHeaderToFhir(cda, fhir_composition, fhir_patient, fhir_bundle) "CdaEimpfHeaderToFhir"; 

      // map the CDA body
      // ClinicalDocument/component
      cda.component as cda_component then {
        // ClinicalDocument/component/structuredBody
        cda_component.structuredBody as cda_structuredBody
          then CdaEimpfBodyToFhir(cda, cda_structuredBody, fhir_composition, fhir_patient, fhir_bundle);
      };
    } "CdaEimpfToFhirBundle";
}

group CdaEimpfHeaderToFhirComposition(source cda: CdaClinicalDocument, target fhir_composition: FhirComposition, target fhir_patient: FhirPatient, target fhir_bundle: FhirBundle) extends CdaHeaderToFhirComposition {
  // ClinicalDocument/code -> Composition.category
  cda.code as cda_code then {
    cda_code.code as code_code ->
    fhir_composition.category as fhir_composition_category,
    fhir_composition_category.coding = translate(code_code, '#cda-eimpf-clinicaldocument-code-2-fhir-category' , 'Coding') "code";
  };

  // ClinicalDocument/code/translation -> Composition.type
  cda.code as cda_code -> fhir_composition.type as fhir_composition_type,
    fhir_composition_type.coding as fhir_composition_type_coding,
    fhir_composition_type_coding.system = 'http://loinc.org',
    fhir_composition_type_coding.code = '60591-5' then {
      cda_code.translation as cda_code_translation then CECodeableConcept(cda_code_translation, fhir_composition_type);
  };
}

group CdaEimpfHeaderToFhir(source cda: CdaClinicalDocument, target fhir_composition: FhirComposition, target fhir_patient: FhirPatient, target fhir_bundle: FhirBundle) extends CdaHeaderToFhir {
}

// _________________________ Section Level Template  _________________________

group CdaEimpfBodyToFhir(source cda: CdaClinicalDocument, source cda_structuredBody: CdaStructuredBody, target fhir_composition: FhirComposition, target fhir_patient: FhirPatient, target fhir_bundle: FhirBundle) {
  // prefill required APS sections in order to have a valid APS instance
  cda_structuredBody -> 
    // section problems
    fhir_composition.section as fhir_composition_problems_section,
    fhir_composition_problems_section.title = 'Gesundheitsprobleme und Risiken (Problems)',
    fhir_composition_problems_section.code as fhir_composition_problems_section_code,
    fhir_composition_problems_section_code.coding as fhir_composition_problems_section_code_coding,
    fhir_composition_problems_section_code_coding.system = 'http://loinc.org',
    fhir_composition_problems_section_code_coding.code = '11450-4',
    fhir_composition_problems_section.emptyReason as fhir_composition_problems_section_emptyReason,
    fhir_composition_problems_section_emptyReason.coding as fhir_composition_problems_section_emptyReason_coding,
    fhir_composition_problems_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_problems_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_problems_section.text as fhir_composition_problems_section_text,
    fhir_composition_problems_section_text.status = 'empty',
    fhir_composition_problems_section_text.div = append('Kein Text für diese Section vorhanden.'),

    // section allergies
    fhir_composition.section as fhir_composition_allergies_section,
    fhir_composition_allergies_section.title = 'Allergien und Intoleranzen (Allergies and Intolerances)',
    fhir_composition_allergies_section.code as fhir_composition_allergies_section_code,
    fhir_composition_allergies_section_code.coding as fhir_composition_allergies_section_code_coding,
    fhir_composition_allergies_section_code_coding.system = 'http://loinc.org',
    fhir_composition_allergies_section_code_coding.code = '48765-2',
    fhir_composition_allergies_section.emptyReason as fhir_composition_allergies_section_emptyReason,
    fhir_composition_allergies_section_emptyReason.coding as fhir_composition_allergies_section_emptyReason_coding,
    fhir_composition_allergies_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_allergies_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_allergies_section.text as fhir_composition_allergies_section_text,
    fhir_composition_allergies_section_text.status = 'empty',
    fhir_composition_allergies_section_text.div = append('Kein Text für diese Section vorhanden.'),

    // section medications
    fhir_composition.section as fhir_composition_medications_section,
    fhir_composition_medications_section.title = 'Medikationsliste (Medication Summary)',
    fhir_composition_medications_section.code as fhir_composition_medications_section_code,
    fhir_composition_medications_section_code.coding as fhir_composition_medications_section_code_coding,
    fhir_composition_medications_section_code_coding.system = 'http://loinc.org',
    fhir_composition_medications_section_code_coding.code = '10160-0',
    fhir_composition_medications_section.emptyReason as fhir_composition_medications_section_emptyReason,
    fhir_composition_medications_section_emptyReason.coding as fhir_composition_medications_section_emptyReason_coding,
    fhir_composition_medications_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_medications_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_medications_section.text as fhir_composition_medications_section_text,
    fhir_composition_medications_section_text.status = 'empty',
    fhir_composition_medications_section_text.div = append('Kein Text für diese Section vorhanden.'),

    // section procedures
    fhir_composition.section as fhir_composition_procedures_section,
    fhir_composition_procedures_section.title = 'Eingriffe und Therapien (History of Procedures)',
    fhir_composition_procedures_section.code as fhir_composition_procedures_section_code,
    fhir_composition_procedures_section_code.coding as fhir_composition_procedures_section_code_coding,
    fhir_composition_procedures_section_code_coding.system = 'http://loinc.org',
    fhir_composition_procedures_section_code_coding.code = '47519-4',
    fhir_composition_procedures_section.emptyReason as fhir_composition_procedures_section_emptyReason,
    fhir_composition_procedures_section_emptyReason.coding as fhir_composition_procedures_section_emptyReason_coding,
    fhir_composition_procedures_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_procedures_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_procedures_section.text as fhir_composition_procedures_section_text,
    fhir_composition_procedures_section_text.status = 'empty',
    fhir_composition_procedures_section_text.div = append('Kein Text für diese Section vorhanden.'),

    // section medical devices
    fhir_composition.section as fhir_composition_devices_section,
    fhir_composition_devices_section.title = 'Implantate, medizinische Geräte (Medical Devices)',
    fhir_composition_devices_section.code as fhir_composition_devices_section_code,
    fhir_composition_devices_section_code.coding as fhir_composition_devices_section_code_coding,
    fhir_composition_devices_section_code_coding.system = 'http://loinc.org',
    fhir_composition_devices_section_code_coding.code = '46264-8',
    fhir_composition_devices_section.emptyReason as fhir_composition_devices_section_emptyReason,
    fhir_composition_devices_section_emptyReason.coding as fhir_composition_devices_section_emptyReason_coding,
    fhir_composition_devices_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_devices_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_devices_section.text as fhir_composition_devices_section_text,
    fhir_composition_devices_section_text.status = 'empty',
    fhir_composition_devices_section_text.div = append('Kein Text für diese Section vorhanden.')

    "prefillRequiredApsSections";
  
  cda_structuredBody.component as cda_component then {

    // Impfungen - kodiert - 1.2.40.0.34.6.0.11.2.1
    // APS section: immunizations
    cda_component.section as cda_section where (code.where(code='11369-6' and codeSystem='2.16.840.1.113883.6.1')) -> 
      fhir_composition.section as fhir_section then CdaEimpfImpfungenKodiertToFhirSection(cda_section, fhir_section, fhir_patient, fhir_bundle);
    
    // Impfindikationsgruppen - kodiert - 1.2.40.0.34.6.0.11.2.4
    // cda_component.section as cda_indikationsgruppen_section where code.where(code='11450-4' and codeSystem='2.16.840.1.113883.6.1') -> fhir_composition.section as fhir_section_2 then CdaIndikationsgruppenSectionToFhirCompositionSection(cda_indikationsgruppen_section, fhir_section_2, fhir_bundle);
    
    // Impfrelevante Erkrankungen - kodiert - 1.2.40.0.34.6.0.11.2.5
    // APS section: History of Past Illness
    cda_component.section as cda_section where code.where(code='11348-0' and codeSystem='2.16.840.1.113883.6.1') -> 
      fhir_composition.section as fhir_section then CdaHistoryOfPastIllnessSectionToFhirCompositionSection(cda_section, fhir_section, fhir_patient, fhir_bundle);
    
    // Antikörper-Bestimmung - kodiert - 1.2.40.0.34.6.0.11.2.7
    // cda_component.section as cda_antikoerper_section where code.where(code='26436-6' and codeSystem='2.16.840.1.113883.6.1') -> fhir_composition.section as fhir_section_4 then CdaAntikoerperSectionToFhirCompositionSection(cda_antikoerper_section, fhir_section_4, fhir_bundle);
    
    // Impfempfehlungen - kodiert - 1.2.40.0.34.6.0.11.2.2
    // APS section: plan of care
    cda_component.section as cda_section where code.where(code='18776-5' and codeSystem='2.16.840.1.113883.6.1') -> 
      fhir_composition.section as fhir_section then CdaEimpfImpfempfehlungKodiertToFhirSection(cda_section, fhir_section, fhir_patient, fhir_bundle);
    

  } "CdaEimpfBodyToFhir";
}

group CdaEimpfImpfungenKodiertToFhirSection(source cda_section: CdaSection, target fhir_section, target fhir_patient: FhirPatient, target fhir_bundle: FhirBundle) extends CdaSectionToFhirSection {
  // section/code -> Composition.section.code
  cda_section.code -> fhir_section.code;

  // section/title
  cda_section -> fhir_section.title = 'Impfungen (Immunizations)' "FhirSectionTitle";

  // section/entry
  cda_section.entry as cda_section_entry then {
    
    // Immunization Entry - 1.2.40.0.34.6.0.11.3.1 -> Immunization
    cda_section_entry where ($this.substanceAdministration.templateId.where(root='1.2.40.0.34.6.0.11.3.1')) then {
      // section/entry/substanceAdministration -> Immunization
      cda_section_entry.substanceAdministration as cda_section_entry_substanceAdministration -> 
        // create Immunization
        fhir_bundle.entry as fhir_bundle_entry,
        fhir_bundle_entry.resource = create('Immunization') as fhir_immunization,
        fhir_immunization.id = uuid() as fhir_immunization_id,
        fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_immunization_id),
        // link section entry to Immunization
        fhir_section.entry = create('Reference') as fhir_section_entry_reference,
        fhir_section_entry_reference.reference = append('urn:uuid:', fhir_immunization_id),
        fhir_section_entry_reference.type = 'Immunization',
        // link Immunization to Patient
        fhir_patient.id as fhir_patient_id,
        fhir_immunization.patient = create('Reference') as fhir_immunization_patient_reference,
        fhir_immunization_patient_reference.reference = append('urn:uuid:', fhir_patient_id),
        fhir_immunization_patient_reference.type = 'Patient' then 
        CdaEimpfSubstanceAdministrationToFhirImmunization(cda_section_entry_substanceAdministration, fhir_immunization, fhir_bundle);
    }; 

    // Immunization Entry Impfung nicht angegeben - 1.2.40.0.34.6.0.11.3.28
    cda_section_entry where ($this.substanceAdministration.templateId.where(root='1.2.40.0.34.6.0.11.3.28')) then {
      cda_section -> fhir_section.emptyReason as fhir_section_emptyReason,
        fhir_section_emptyReason.coding as fhir_section_emptyReason_coding,
        fhir_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
        fhir_section_emptyReason_coding.code = 'nilknown',
        fhir_section_emptyReason_coding.display = 'Nil Known';
    };
  };

  // Übersetzung
  // currently not necessary to be mapped:
  //   Since the section/text is not displayed, the translation is irrelevant in that context.
}

// Mapping of Section: Immunization-Relevant Conditions - Coded - https://art-decor.org/ad/#/elgaimpf-/rules/templates/1.2.40.0.34.6.0.11.2.5/2026-01-16T12:18:59
group CdaHistoryOfPastIllnessSectionToFhirCompositionSection(source cda_section: CdaSection, target fhir_section, target fhir_patient: FhirPatient, target fhir_bundle: FhirBundle) extends CdaSectionToFhirSection {

  
  // section/code -> Composition.section.code
  cda_section.code -> fhir_section.code; 
  
  // section/title -> Composition.section.title
  cda_section -> fhir_section.title = 'Gesundheitsprobleme und Risiken (Problems)' "FhirSectionTitle";

  // section/entry -> Condition 
  cda_section.entry as cda_section_entry then {
    // section/entry/act
    cda_section_entry.act as cda_section_entry_act -> 
      fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('Condition') as fhir_condition,
      fhir_condition.id = uuid() as fhir_condition_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_condition_id),
      fhir_section.entry = create('Reference') as fhir_section_entry_reference,
      fhir_section_entry_reference.reference = append('urn:uuid:', fhir_condition_id),
      fhir_section_entry_reference.type = 'Condition',
      fhir_patient.id as fhir_patient_id,
      fhir_condition.subject = create('Reference') as fhir_condition_subject_reference,
      fhir_condition_subject_reference.reference = append('urn:uuid:', fhir_patient_id),
      fhir_condition_subject_reference.type = 'Patient' then 
        CdaHistoryOfPastIllnessActToFhirCondition(cda_section_entry_act, cda_section, fhir_condition, fhir_patient, fhir_bundle);
  };
}

group CdaEimpfImpfempfehlungKodiertToFhirSection(source cda_section: CdaSection, target fhir_section, target fhir_patient: FhirPatient, target fhir_bundle: FhirBundle) extends CdaSectionToFhirSection {
  // section/code -> Composition.section.code
  cda_section.code -> fhir_section.code;

  // section/title
  cda_section -> fhir_section.title = 'Behandlungsplan (Plan of Care)' "FhirSectionTitle";

  // section/entry
  cda_section.entry as cda_section_entry then {
    // section/entry/substanceAdministration -> ImmunizationRecommendation
    cda_section_entry.substanceAdministration as cda_section_entry_substanceAdministration -> 
      // create ImmunizationRecommendation
      fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('ImmunizationRecommendation') as fhir_immunizationRecommendation,
      fhir_immunizationRecommendation.id = uuid() as fhir_immunizationRecommendation_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_immunizationRecommendation_id),
      // link section entry to ImmunizationRecommendation
      fhir_section.entry = create('Reference') as fhir_section_entry_reference,
      fhir_section_entry_reference.reference = append('urn:uuid:', fhir_immunizationRecommendation_id),
      fhir_section_entry_reference.type = 'ImmunizationRecommendation',
      // link ImmunizationRecommendation to Patient
      fhir_patient.id as fhir_patient_id,
      fhir_immunizationRecommendation.patient = create('Reference') as fhir_immunizationRecommendation_patient_reference,
      fhir_immunizationRecommendation_patient_reference.reference = append('urn:uuid:', fhir_patient_id),
      fhir_immunizationRecommendation_patient_reference.type = 'Patient' then 
      CdaEimpfSubstanceAdministrationToFhirImmunizationRecommendation(cda_section, cda_section_entry_substanceAdministration, fhir_immunizationRecommendation, fhir_bundle);
  };

  // Übersetzung
  // currently not necessary to be mapped:
  //   Since the section/text is not displayed, the translation is irrelevant in that context.
}

// _________________________ Entry Level Template  _________________________

group CdaEimpfSubstanceAdministrationToFhirImmunization(source cda_substanceAdministration: CdaSubstanceAdministration, target fhir_immunization: FhirImmunization, target fhir_bundle: FhirBundle) {
  // substanceAdministration/id -> Immunization.identifier 
  cda_substanceAdministration.id -> fhir_immunization.identifier;

  // substanceAdministration/text
  // currently not necessary to be mapped:
  //   Within the text element, references are made to sections of the section/text. 
  //   Since the "Complete Immunization Status" currently displays only coded information, 
  //   this element is not included.

  // substanceAdministration/statusCode -> Immunization.status
  cda_substanceAdministration.statusCode -> fhir_immunization.status; 

  // substanceAdministration/effectiveTime -> Immunization.occurrenceDateTime
  cda_substanceAdministration.effectiveTime as cda_substanceAdministration_effectiveTime -> 
    fhir_immunization.occurrence = create('dateTime') as fhir_immunization_occurrence then TSDateTime(cda_substanceAdministration_effectiveTime, fhir_immunization_occurrence) 
    "CdaEffectiveTimeToFhirOccurrenceDateTime";
  
  // substanceAdministration/routeCode -> Immunization.route
  cda_substanceAdministration.routeCode where ($this.nullFlavor.exists().not()) -> fhir_immunization.route;

  // substanceAdministration/doseQuantity -> AtApsImmunization.doseQuantity
  cda_substanceAdministration.doseQuantity as cda_substanceAdministration_doseQuantity where ($this.nullFlavor.exists().not()) -> 
    fhir_immunization.doseQuantity as fhir_immunization_doseQuantity then
    PQQuantity(cda_substanceAdministration_doseQuantity, fhir_immunization_doseQuantity)
    "CdaDoseQuantityToFhirDoseQuantity";

  // substanceAdministration/consumable
  cda_substanceAdministration.consumable as cda_consumable then {
    // substanceAdministration/consumable/manufacturedProduct
    cda_consumable.manufacturedProduct as cda_manufacturedProduct then {
      // substanceAdministration/consumable/manufacturedProduct/id
      // TODO

      // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial
      cda_manufacturedProduct.manufacturedMaterial as cda_manufacturedMaterial then {
        // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/name -> Immunization.vaccineCode
        cda_manufacturedMaterial -> 
          fhir_immunization.vaccineCode as fhir_immunization_vaccineCode then 
            CdaVaccineCodeToFhirVaccineCode(cda_manufacturedMaterial, fhir_immunization_vaccineCode);

        // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/name
        //TODO

        // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/lotNumberText -> Immunization.lotNumber
        cda_manufacturedMaterial.lotNumberText where ($this.nullFlavor.exists().not()) -> fhir_immunization.lotNumber;

        // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/pharm:ingredient
        // TODO
      };

      // substanceAdministration/consumable/manufacturedProduct/manufacturerOrganization -> Immunization.manufacturer
      cda_manufacturedProduct.manufacturerOrganization as cda_manufacturerOrganization ->
        fhir_bundle.entry as fhir_bundle_entry,
        fhir_bundle_entry.resource = create('Organization') as fhir_organization,
        fhir_organization.id = uuid() as fhir_organization_id,
        fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_organization_id),
        fhir_immunization.manufacturer = create('Reference') as fhir_immunization_organization_reference,
        fhir_immunization_organization_reference.reference = append('urn:uuid:', fhir_organization_id),
        fhir_immunization_organization_reference.type = 'Organization' then
        CdaOrganizationCompilationToFhirOrganization(cda_manufacturerOrganization, fhir_organization);
    };
  };

  // substanceAdministration/performer -> Immunization.performer and Provenance
  cda_substanceAdministration.performer as cda_substanceAdministration_performer ->
    // create Provenance
    fhir_bundle.entry as fhir_bundle_entry01,
    fhir_bundle_entry01.resource = create('Provenance') as fhir_provenance,
    fhir_provenance.id = uuid() as fhir_provenance_id,
    fhir_bundle_entry01.fullUrl = append('urn:uuid:', fhir_provenance_id),
    // link Immunization to Provenance.target
    fhir_immunization.id as fhir_immunization_id,
    fhir_provenance.target = create('Reference') as fhir_provenance_target_reference,
    fhir_provenance_target_reference.reference = append('urn:uuid:', fhir_immunization_id),
    fhir_provenance_target_reference.type = 'Immunization',
    // create PractitionerRole in order to use it as Immunization.performer
    fhir_bundle.entry as fhir_bundle_entry02,
    fhir_bundle_entry02.resource = create('PractitionerRole') as fhir_practitionerRole,
    fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
    fhir_bundle_entry02.fullUrl = append('urn:uuid:', fhir_practitionerRole_id),
    // link PractitionerRole to Immunization.perfomer
    fhir_immunization.performer as fhir_immunization_performer,
    fhir_immunization_performer.actor = create('Reference') as fhir_immunization_performer_actor_reference,
    fhir_immunization_performer_actor_reference.reference = append('urn:uuid:', fhir_practitionerRole_id),
    fhir_immunization_performer_actor_reference.type = 'PractitionerRole',
    // set Immunization.performer.function
    fhir_immunization_performer.function as fhir_immunization_performer_function,
    fhir_immunization_performer_function.coding as fhir_immunization_performer_function_coding,
    fhir_immunization_performer_function_coding.system = 'http://terminology.hl7.org/CodeSystem/v2-0443',
    fhir_immunization_performer_function_coding.code = 'AP' then 
      CdaPerformerToFhirProvenance(cda_substanceAdministration_performer, fhir_provenance, fhir_practitionerRole, fhir_bundle);

  // substanceAdministration/author -> Immunization.performer and Provenance
  // if author is a person
  cda_substanceAdministration.author as cda_substanceAdministration_author where ($this.assignedAuthor.assignedPerson.exists()) -> 
    // create Provenance
    fhir_bundle.entry as fhir_bundle_entry01,
    fhir_bundle_entry01.resource = create('Provenance') as fhir_provenance,
    fhir_provenance.id = uuid() as fhir_provenance_id,
    fhir_bundle_entry01.fullUrl = append('urn:uuid:', fhir_provenance_id),
    // link Immunization to Provenance.target
    fhir_immunization.id as fhir_immunization_id,
    fhir_provenance.target = create('Reference') as fhir_provenance_target_reference,
    fhir_provenance_target_reference.reference = append('urn:uuid:', fhir_immunization_id),
    fhir_provenance_target_reference.type = 'Immunization',
    // create PractitionerRole in order to use it as Immunization.performer
    fhir_bundle.entry as fhir_bundle_entry02,
    fhir_bundle_entry02.resource = create('PractitionerRole') as fhir_practitionerRole,
    fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
    fhir_bundle_entry02.fullUrl = append('urn:uuid:', fhir_practitionerRole_id),
    // link PractitionerRole to Immunization.perfomer
    fhir_immunization.performer as fhir_immunization_performer,
    fhir_immunization_performer.actor = create('Reference') as fhir_immunization_performer_actor_reference,
    fhir_immunization_performer_actor_reference.reference = append('urn:uuid:', fhir_practitionerRole_id),
    fhir_immunization_performer_actor_reference.type = 'PractitionerRole',
    // set Immunization.performer.function
    fhir_immunization_performer.function as fhir_immunization_performer_function,
    fhir_immunization_performer_function.coding as fhir_immunization_performer_function_coding,
    fhir_immunization_performer_function_coding.system = 'http://terminology.hl7.org/CodeSystem/v2-0443',
    fhir_immunization_performer_function_coding.code = 'OP' then 
      CdaAuthorPersonToFhirProvenance(cda_substanceAdministration_author, fhir_provenance, fhir_practitionerRole, fhir_bundle);

  // substanceAdministration/author -> Provenance
  // if author is a device
  cda_substanceAdministration.author as cda_substanceAdministration_author where ($this.assignedAuthor.assignedAuthoringDevice.exists()) -> 
    // create Provenance
    fhir_bundle.entry as fhir_bundle_entry,
    fhir_bundle_entry.resource = create('Provenance') as fhir_provenance,
    fhir_provenance.id = uuid() as fhir_provenance_id,
    fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_provenance_id),
    // link Immunization to Provenance.target
    fhir_immunization.id as fhir_immunization_id,
    fhir_provenance.target = create('Reference') as fhir_provenance_target_reference,
    fhir_provenance_target_reference.reference = append('urn:uuid:', fhir_immunization_id),
    fhir_provenance_target_reference.type = 'Immunization' then
      CdaAuthorDeviceToFhirProvenance(cda_substanceAdministration_author, fhir_provenance, fhir_bundle);

  // substanceAdministration/informant
  // currently not necessary to be mapped:
  //   Self-reporting of vaccinations has not yet been implemented. 
  //   Therefore, it is not currently relevant for mapping.

  // substanceAdministration/participant[@typeCode!='AUT'] -> Provenance
  // Participant Body - Authorized Editor = Berechtigter bearbeitender GDA (OID aus dem GDA-Index) (@typeCode = 'AUT') is currently ignored
  cda_substanceAdministration.participant as cda_participant where ($this.typeCode != 'AUT') -> 
    fhir_bundle.entry as fhir_bundle_entry,
    fhir_bundle_entry.resource = create('Provenance') as fhir_provenance,
    fhir_provenance.id = uuid() as fhir_provenance_id,
    fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_provenance_id),
    fhir_immunization.id as fhir_immunization_id,
    fhir_provenance.target = create('Reference') as fhir_provenance_target_reference,
    fhir_provenance_target_reference.reference = append('urn:uuid:', fhir_immunization_id),
    fhir_provenance_target_reference.type = 'Immunization' then 
      CdaParticipantToFhirProvenance(cda_participant, fhir_provenance, fhir_bundle);

  cda_substanceAdministration -> fhir_immunization.protocolApplied as fhir_immunization_protocolApplied then {
    
    // substanceAdministration/entryRelationship (Immunization Target Entry)
    cda_substanceAdministration.entryRelationship as cda_substanceAdministration_entryRelationship where ($this.observation.templateId.where(root='1.2.40.0.34.6.0.11.3.2')) then {
      cda_substanceAdministration_entryRelationship.observation as cda_observation then {
        // substanceAdministration/entryRelationship/observation/code -> Immunization.protocolApplied.targetDisease
        cda_observation.code -> fhir_immunization_protocolApplied.targetDisease;
      };
    };
      
    // substanceAdministration/precondition (Immunization Schedule Entry)
    cda_substanceAdministration.precondition as cda_substanceAdministration_precondition then {
      // substanceAdministration/precondition/criterion
      cda_substanceAdministration_precondition.criterion as cda_criterion then {
        // substanceAdministration/precondition/criterion/code -> Immunization.protocolApplied.series
        cda_criterion.code as cda_criterion_code where ($this.nullFlavor.exists().not()) then {
          // substanceAdministration/precondition/criterion/code/@code -> Immunization.protocolApplied.series
          cda_criterion_code.code as cda_criterion_code_code ->
            fhir_immunization_protocolApplied.series = cast(cda_criterion_code_code, 'string') as fhir_immunization_protocolApplied_series,
            fhir_immunization_protocolApplied_series.extension as fhir_immunization_protocolApplied_series_extension,
            fhir_immunization_protocolApplied_series_extension.url = 'http://hl7.org/fhir/StructureDefinition/iso21090-codedString',
            fhir_immunization_protocolApplied_series_extension.value = create('Coding') as fhir_coding then 
              // substanceAdministration/precondition/criterion/code -> Immunization.protocolApplied.series.extension.coding
              CECoding(cda_criterion_code, fhir_coding);
        };

        // substanceAdministration/precondition/criterion/value -> Immunization.protocolApplied.doseNumberString
        cda_criterion.value as cda_criterion_value where ($this.nullFlavor.exists().not()) then {
          cda_criterion_value.code as cda_criterion_value_code ->
            fhir_immunization_protocolApplied.doseNumber = cast(cda_criterion_value_code, 'string') as fhir_immunization_protocolApplied_doseNumber,
            fhir_immunization_protocolApplied_doseNumber.extension as fhir_immunization_protocolApplied_doseNumber_extension,
            fhir_immunization_protocolApplied_doseNumber_extension.url = 'http://hl7.org/fhir/StructureDefinition/iso21090-codedString',
            fhir_immunization_protocolApplied_doseNumber_extension.value = create('Coding') as fhir_coding then 
              // substanceAdministration/precondition/criterion/value -> Immunization.protocolApplied.doseNumberString.extension.coding
              CECoding(cda_criterion_value, fhir_coding);
        };
        // substanceAdministration/precondition/criterion/value -> Immunization.protocolApplied.doseNumberString
        // based on https://hl7.eu/fhir/base-r5/missing-data.html
        cda_criterion.value as cda_criterion_value where ($this.nullFlavor.exists()) -> 
          fhir_immunization_protocolApplied.doseNumber = create('string') as fhir_immunization_protocolApplied_doseNumber,
          fhir_immunization_protocolApplied_doseNumber.extension as fhir_immunization_protocolApplied_doseNumber_extension then
          CdaNullFlavorToFhirDataAbsentReason(cda_criterion_value, fhir_immunization_protocolApplied_doseNumber_extension); 
      }; 
    }; 
  };

  // substanceAdministration/entryRelationship (Immunization Billability Entry)
  // currently not necessary to be mapped:
  //    This has not yet been implemented. Therefore, it is not currently relevant for the mapping.

  // substanceAdministration/entryRelationship (Zusatzklassifikation)
  cda_substanceAdministration.entryRelationship as cda_substanceAdministration_entryRelationship where ($this.observation.templateId.where(root='1.2.40.0.34.6.0.11.3.168')) then {
    // Impfsetting
    cda_substanceAdministration_entryRelationship.observation as cda_observation where ($this.code.where(code='46224007')) then {
      cda_observation.value as cda_observation_value then {
        // substanceAdministration/entryRelationship/observation/value -> Immunization.location.display
        cda_observation_value.code as cda_observation_value_code ->
          fhir_immunization.location as fhir_immunization_location,
          fhir_immunization_location.display = cast(cda_observation_value_code, 'string') as fhir_immunization_location_display,
          fhir_immunization_location_display.extension as fhir_immunization_location_display_extension,
          fhir_immunization_location_display_extension.url = 'http://hl7.org/fhir/StructureDefinition/iso21090-codedString',
          fhir_immunization_location_display_extension.value = create('Coding') as fhir_coding then 
            // substanceAdministration/entryRelationship/observation/value -> Immunization.location.display.extension.coding
            CDCoding(cda_observation_value, fhir_coding);
      };
    };
    // Impfprogramm
    cda_substanceAdministration_entryRelationship.observation as cda_observation where ($this.code.where(code='IS009')) then {
      // substanceAdministration/entryRelationship/observation/value -> Immunization.fundingSource
      cda_observation.value: CD -> fhir_immunization.fundingSource; 
    };
  };

  // substanceAdministration/reference/externalDocument -> Immunization.identifier
  cda_substanceAdministration.reference as cda_substanceAdministration_reference then {
    cda_substanceAdministration_reference.externalDocument as cda_substanceAdministration_reference_externalDocument then {
      cda_substanceAdministration_reference_externalDocument.id as cda_substanceAdministration_reference_externalDocument_id -> 
        fhir_immunization.identifier as fhir_immunization_identifier,
        fhir_immunization_identifier.use = 'secondary' then II(cda_substanceAdministration_reference_externalDocument_id, fhir_immunization_identifier) then {
          cda_substanceAdministration_reference_externalDocument.code -> fhir_immunization_identifier.type;
        };
    };
  };
}

group CdaEimpfSubstanceAdministrationToFhirImmunizationRecommendation(source cda_section: CdaSection, source cda_substanceAdministration: CdaSubstanceAdministration, target fhir_immunizationRecommendation: FhirImmunizationRecommendation, target fhir_bundle: FhirBundle) {
  // substanceAdministration/id -> ImmunizationRecommendation.identifier 
  cda_substanceAdministration.id -> fhir_immunizationRecommendation.identifier;
  // ToDo: 
  // Check if this { is closed properly
  cda_substanceAdministration -> fhir_immunizationRecommendation.recommendation as fhir_immunizationRecommendation_recommendation then {
    // substanceAdministration/code -> fhir_immunizationRecommendation.recommendation.forecastStatus
    cda_substanceAdministration.code -> fhir_immunizationRecommendation_recommendation.forecastStatus;

    // substanceAdministration/text
    // currently not necessary to be mapped:
    //   Within the text element, references are made to sections of the section/text. 
    //   Since the "Complete Immunization Status" currently displays only coded information, 
    //   this element is not included.

    // substanceAdministration/statusCode
    // currently not necessary to be mapped:
    //    Constant code in CDA won't be mapped to FHIR as there is no resemblance in FHIR.

    // substanceAdministration/effectiveTime
    cda_substanceAdministration.effectiveTime as cda_substanceAdministration_effectiveTime then {

      cda_substanceAdministration_effectiveTime.low as cda_effectiveTime_low where ($this.value.exists()) -> 
        fhir_immunizationRecommendation_recommendation.dateCriterion as fhir_recommendation_dateCriterion,
        fhir_recommendation_dateCriterion.code as fhir_recommendation_dateCriterion_code, 
        fhir_recommendation_dateCriterion_code.coding as fhir_dateCriterion_code_coding, 
        fhir_dateCriterion_code_coding.system = 'http://loinc.org',
        fhir_dateCriterion_code_coding.code = '30981-5',
        fhir_recommendation_dateCriterion.value as fhir_dateCriterion_value then TSDateTime(cda_effectiveTime_low,fhir_dateCriterion_value);
    
      cda_substanceAdministration_effectiveTime.high as cda_effectiveTime_high where ($this.value.exists()) -> 
        fhir_immunizationRecommendation_recommendation.dateCriterion as fhir_recommendation_dateCriterion,
        fhir_recommendation_dateCriterion.code as fhir_recommendation_dateCriterion_code, 
        fhir_recommendation_dateCriterion_code.coding as fhir_dateCriterion_code_coding, 
        fhir_dateCriterion_code_coding.system = 'http://loinc.org',
        fhir_dateCriterion_code_coding.code = '59777-3',
        fhir_recommendation_dateCriterion.value as fhir_dateCriterion_value then TSDateTime(cda_effectiveTime_high,fhir_dateCriterion_value);
    };     

    // substanceAdministration/doseQuantity
    cda_substanceAdministration.doseQuantity as cda_substanceAdministration_doseQuantity where ($this.nullFlavor.exists().not()) -> 
      fhir_immunizationRecommendation.extension as fhir_immunizationRecommendation_extension,
      fhir_immunizationRecommendation_extension.url = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-ext-immunizationRecommendation-doseQuantity',
      fhir_immunizationRecommendation_extension.valueQuantity = create('Quantity') as fhir_immunizationRecommendation_extension_valueQuantity then
      PQQuantity(cda_substanceAdministration_doseQuantity, fhir_immunizationRecommendation_extension_valueQuantity);


    // substanceAdministration/consumable
    cda_substanceAdministration.consumable as cda_consumable then {
      // substanceAdministration/consumable/manufacturedProduct
      cda_consumable.manufacturedProduct as cda_manufacturedProduct then {
        // substanceAdministration/consumable/manufacturedProduct/id
        // TODO

        // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial
        cda_manufacturedProduct.manufacturedMaterial as cda_manufacturedMaterial then {
          // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/code -> ImmunizationRecommendation.recommendation.vaccineCode
          cda_substanceAdministration.negationInd as cda_substanceAdministration_negationInd where ($this = false) then {
            cda_manufacturedMaterial -> 
              fhir_immunizationRecommendation_recommendation.vaccineCode as fhir_immunizationRecommendation_recommendation_vaccineCode then 
                CdaVaccineCodeToFhirVaccineCode(cda_manufacturedMaterial, fhir_immunizationRecommendation_recommendation_vaccineCode);
          };
          // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/code -> ImmunizationRecommendation.recommendation.contraindicatedVaccineCode
          cda_substanceAdministration.negationInd as cda_substanceAdministration_negationInd where ($this = true) then {
            cda_manufacturedMaterial -> 
              fhir_immunizationRecommendation_recommendation.contraindicatedVaccineCode as fhir_immunizationRecommendation_recommendation_contraindicatedVaccineCode then 
                CdaVaccineCodeToFhirVaccineCode(cda_manufacturedMaterial, fhir_immunizationRecommendation_recommendation_contraindicatedVaccineCode);
          };

          // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/name
          //TODO

          // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/lotNumberText
          // not to be mapped:
          //   In case of immunization recommendations the logNumberText cannot be mapped because it is not applicable

          // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/pharm:ingredient
          // TODO
        };

        // substanceAdministration/consumable/manufacturedProduct/manufacturerOrganization
        // TODO
      };
    };

    // substanceAdministration/author
    // if author is a person
    cda_substanceAdministration.author as cda_substanceAdministration_author where ($this.assignedAuthor.assignedPerson.exists()) -> 
      // create Provenance
      fhir_bundle.entry as fhir_bundle_entry01,
      fhir_bundle_entry01.resource = create('Provenance') as fhir_provenance,
      fhir_provenance.id = uuid() as fhir_provenance_id,
      fhir_bundle_entry01.fullUrl = append('urn:uuid:', fhir_provenance_id),
      // link ImmunizationRecommendation to Provenance.target
      fhir_immunizationRecommendation.id as fhir_immunizationRecommendation_id,
      fhir_provenance.target = create('Reference') as fhir_provenance_target_reference,
      fhir_provenance_target_reference.reference = append('urn:uuid:', fhir_immunizationRecommendation_id),
      fhir_provenance_target_reference.type = 'ImmunizationRecommendation',
      // create PractitionerRole in order to use it as Immunization.performer
      fhir_bundle.entry as fhir_bundle_entry02,
      fhir_bundle_entry02.resource = create('PractitionerRole') as fhir_practitionerRole,
      fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
      fhir_bundle_entry02.fullUrl = append('urn:uuid:', fhir_practitionerRole_id) then { 
        // substanceAdministration/author -> ImmunizationRecommendation.date
        cda_substanceAdministration_author.time where ($this.nullFlavor.exists().not()) -> fhir_immunizationRecommendation.date;
        // substanceAdministration/author -> ImmunizationRecommendation.date
        // based on https://hl7.eu/fhir/base-r5/missing-data.html
        cda_substanceAdministration_author.time as cda_substanceAdministration_author_time where ($this.nullFlavor.exists()) -> 
          fhir_immunizationRecommendation.date as fhir_immunizationRecommendation_date,
          fhir_immunizationRecommendation_date.extension as fhir_immunizationRecommendation_date_extension
          then CdaNullFlavorToFhirDataAbsentReason(cda_substanceAdministration_author_time, fhir_immunizationRecommendation_date_extension);

        // substanceAdministration/author -> Provenance
        cda_substanceAdministration_author then CdaAuthorPersonToFhirProvenance(cda_substanceAdministration_author, fhir_provenance, fhir_practitionerRole, fhir_bundle);
      };

    // substanceAdministration/author
    // if author is a device
    cda_substanceAdministration.author as cda_substanceAdministration_author where ($this.assignedAuthor.assignedAuthoringDevice.exists()) -> 
      // create Provenance
      fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('Provenance') as fhir_provenance,
      fhir_provenance.id = uuid() as fhir_provenance_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_provenance_id),
      // link ImmunizationRecommendation to Provenance.target
      fhir_immunizationRecommendation.id as fhir_immunizationRecommendation_id,
      fhir_provenance.target = create('Reference') as fhir_provenance_target_reference,
      fhir_provenance_target_reference.reference = append('urn:uuid:', fhir_immunizationRecommendation_id),
      fhir_provenance_target_reference.type = 'ImmunizationRecommendation' then {
        // substanceAdministration/author -> ImmunizationRecommendation.date
        cda_substanceAdministration_author.time where ($this.nullFlavor.exists().not()) -> fhir_immunizationRecommendation.date;
        // substanceAdministration/author -> ImmunizationRecommendation.date
        // based on https://hl7.eu/fhir/base-r5/missing-data.html
        cda_substanceAdministration_author.time as cda_substanceAdministration_author_time where ($this.nullFlavor.exists()) -> 
          fhir_immunizationRecommendation.date as fhir_immunizationRecommendation_date,
          fhir_immunizationRecommendation_date.extension as fhir_immunizationRecommendation_date_extension
          then CdaNullFlavorToFhirDataAbsentReason(cda_substanceAdministration_author_time, fhir_immunizationRecommendation_date_extension);

        // substanceAdministration/author -> Provenance
        cda_substanceAdministration_author then CdaAuthorDeviceToFhirProvenance(cda_substanceAdministration_author, fhir_provenance, fhir_bundle);
      };

    // substanceAdministration/participant[@typeCode!='AUT'] -> Provenance
    // Participant Body - Authorized Editor = Berechtigter bearbeitender GDA (OID aus dem GDA-Index) (@typeCode = 'AUT') is currently ignored
    cda_substanceAdministration.participant as cda_participant where ($this.typeCode != 'AUT') -> 
      fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('Provenance') as fhir_provenance,
      fhir_provenance.id = uuid() as fhir_provenance_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_provenance_id),
      fhir_immunizationRecommendation.id as fhir_immunizationRecommendation_id,
      fhir_provenance.target = create('Reference') as fhir_provenance_target_reference,
      fhir_provenance_target_reference.reference = append('urn:uuid:', fhir_immunizationRecommendation_id),
      fhir_provenance_target_reference.type = 'ImmunizationRecommendation' then 
        CdaParticipantToFhirProvenance(cda_participant, fhir_provenance, fhir_bundle);

    // substanceAdministration/entryRelationship (Immunization Target Entry)
    cda_substanceAdministration.entryRelationship as cda_substanceAdministration_entryRelationship where ($this.observation.templateId.where(root='1.2.40.0.34.6.0.11.3.2')) then {
      cda_substanceAdministration_entryRelationship.observation as cda_observation then {
        // substanceAdministration/entryRelationship/observation/code -> ImmunizationRecommendation.recommendation.targetDisease
        cda_observation.code -> fhir_immunizationRecommendation_recommendation.targetDisease;
      };
    };

    // substanceAdministration/entryRelationship (Comment Entry)
    cda_substanceAdministration.entryRelationship as cda_substanceAdministration_entryRelationship where ($this.act.templateId.where(root='1.2.40.0.34.6.0.11.3.17')) then {
      // substanceAdministration/entryRelationship/act
      cda_substanceAdministration_entryRelationship.act as cda_act then {
        // substanceAdministration/entryRelationship/act/text
        cda_act.text as cda_act_text then {
          // substanceAdministration/entryRelationship/act/text/reference
          cda_act_text.reference as cda_act_text_reference then {
            cda_section.text as cda_section_text then {
              // substanceAdministration/entryRelationship/act/text/reference/@value -> ImmunizationRecommendation.recommendation.description
              cda_act_text_reference.value as cda_act_text_reference_value -> 
                // Create Narrative (same datatype as in Composition.section.text)
                create('Narrative') as fhir_narrative, 
                // section/text -> Narrative.div
                fhir_narrative.div = cda_section_text as fhir_narrative_div,
                
                // Create string
                create('string') as fhir_string,
                // Convert test_div to a FHIR string
                fhir_string = (fhir_narrative_div),

                // Create substring from the ID (identified by cda_act_text_reference_value) till the end of fhir_string
                create('string') as fhir_substring_01,
                // cda_act_text_reference_value.substring(1) = removing '#' from reference/@value (e.g. '#commentRef-1' becomes 'commentRef-1')
                // fhir_string.indexOf(cda_act_text_reference_value.substring(1)) = the position of the ID within section/text
                fhir_substring_01 = (fhir_string.substring(fhir_string.indexOf(cda_act_text_reference_value.substring(1)))),

                // Create a substring from the first occurrence of > character till the end of fhir_substring_01
                create('string') as fhir_substring_02,
                fhir_substring_02 = (fhir_substring_01.substring(fhir_substring_01.indexOf('>') + 1)),

                // Create a substring from the start till the first occurrence of < character
                fhir_immunizationRecommendation_recommendation.description = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')));
            };
          };
        };
      };
    };

    // substanceAdministration/reference/externalDocument -> Immunization.identifier
    cda_substanceAdministration.reference as cda_substanceAdministration_reference where ($this.externalDocument.templateId.where(root='1.2.40.0.34.6.0.11.3.14')) then {
        cda_substanceAdministration_reference.externalDocument as cda_substanceAdministration_reference_externalDocument then {
          cda_substanceAdministration_reference_externalDocument.id as cda_substanceAdministration_reference_externalDocument_id -> fhir_immunizationRecommendation.identifier as fhir_immunizationRecommendation_identifier,
          fhir_immunizationRecommendation_identifier.use = 'secondary' then II(cda_substanceAdministration_reference_externalDocument_id, fhir_immunizationRecommendation_identifier) then {
            cda_substanceAdministration_reference_externalDocument.code -> fhir_immunizationRecommendation_identifier.type; 
          };
        };
    };

    // substanceAdministration/precondition (Immunization Schedule Entry)
    cda_substanceAdministration.precondition as cda_substanceAdministration_precondition then {
      // substanceAdministration/precondition/criterion
      cda_substanceAdministration_precondition.criterion as cda_criterion then {
        // substanceAdministration/precondition/criterion/code -> Immunization.protocolApplied.series
        cda_criterion.code as cda_criterion_code where ($this.nullFlavor.exists().not()) then {
          // substanceAdministration/precondition/criterion/code/@code -> Immunization.protocolApplied.series
          cda_criterion_code.code as cda_criterion_code_code ->
            fhir_immunizationRecommendation_recommendation.series = cast(cda_criterion_code_code, 'string') as fhir_immunizationRecommendation_recommendation_series,
            fhir_immunizationRecommendation_recommendation_series.extension as fhir_immunizationRecommendation_recommendation_series_extension,
            fhir_immunizationRecommendation_recommendation_series_extension.url = 'http://hl7.org/fhir/StructureDefinition/iso21090-codedString',
            fhir_immunizationRecommendation_recommendation_series_extension.value = create('Coding') as fhir_coding then 
              // substanceAdministration/precondition/criterion/code -> Immunization.protocolApplied.series.extension.coding
              CECoding(cda_criterion_code, fhir_coding);
        };

        // substanceAdministration/precondition/criterion/value -> Immunization.protocolApplied.doseNumberString
        cda_criterion.value as cda_criterion_value where ($this.nullFlavor.exists().not()) then {
          cda_criterion_value.code as cda_criterion_value_code ->
            fhir_immunizationRecommendation_recommendation.doseNumber = cast(cda_criterion_value_code, 'string') as fhir_immunizationRecommendation_recommendation_doseNumber,
            fhir_immunizationRecommendation_recommendation_doseNumber.extension as fhir_immunizationRecommendation_recommendation_doseNumber_extension,
            fhir_immunizationRecommendation_recommendation_doseNumber_extension.url = 'http://hl7.org/fhir/StructureDefinition/iso21090-codedString',
            fhir_immunizationRecommendation_recommendation_doseNumber_extension.value = create('Coding') as fhir_coding then 
              // substanceAdministration/precondition/criterion/value -> Immunization.protocolApplied.doseNumberString.extension.coding
              CECoding(cda_criterion_value, fhir_coding);
        };
        // substanceAdministration/precondition/criterion/value -> Immunization.protocolApplied.doseNumberString
        // based on https://hl7.eu/fhir/base-r5/missing-data.html
        cda_criterion.value as cda_criterion_value where ($this.nullFlavor.exists()) -> 
          fhir_immunizationRecommendation_recommendation.doseNumber = create('string') as fhir_immunizationRecommendation_recommendation_doseNumber,
          fhir_immunizationRecommendation_recommendation_doseNumber.extension as fhir_immunizationRecommendation_recommendation_doseNumber_extension then 
          CdaNullFlavorToFhirDataAbsentReason(cda_criterion_value, fhir_immunizationRecommendation_recommendation_doseNumber_extension); 
      }; 
    }; 
  };
}

group CdaVaccineCodeToFhirVaccineCode(source cda_manufacturedMaterial: CdaMaterial, target fhir_vaccineCode: FhirCodeableConcept) {
  // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/code -> fhir_vaccineCode
  // nullFlavor = 'NA' covers Vaccine Product nicht angegeben - 1.2.40.0.34.6.0.11.9.31
  // based on https://hl7.eu/fhir/base-r5/missing-data.html
  cda_manufacturedMaterial.code as cda_manufacturedMaterial_code where ($this.nullFlavor = 'NA' or $this.nullFlavor = 'OTH') then {
    cda_manufacturedMaterial_code.nullFlavor as cda_manufacturedMaterial_code_nullFlavor ->
      fhir_vaccineCode.coding as fhir_vaccineCode_coding,
      fhir_vaccineCode_coding.system = 'http://terminology.hl7.org/CodeSystem/data-absent-reason',
      fhir_vaccineCode_coding.code = translate(cda_manufacturedMaterial_code_nullFlavor, '#v3-NullFlavor-2-data-absent-reason', 'code');
  };

  // substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/code -> fhir_vaccineCode
  cda_manufacturedMaterial.code as cda_manufacturedMaterial_code where ($this.nullFlavor.exists().not()) then CECodeableConcept(cda_manufacturedMaterial_code, fhir_vaccineCode); 
}

//Mapping of Templates: 
  // Immunization-Relevant Conditions Problem Concern Entry - https://art-decor.org/ad/#/elgaimpf-/rules/templates/1.2.40.0.34.6.0.11.3.8/2023-03-31T12:18:19
  // Immunization-Relevant Conditions Problem Entry - https://art-decor.org/ad/#/elgaimpf-/rules/templates/1.2.40.0.34.6.0.11.3.9/2023-03-30T08:46:35
group CdaHistoryOfPastIllnessActToFhirCondition(source cda_act: CdaAct, source cda_section: CdaSection, target fhir_condition: Condition, source fhir_patient: Patient, target fhir_bundle: Bundle){
  //---------------------------------------
  // ToDo: 
    // 1. Check if Mapping is needed for following templates:  

        //Template: Immunization-Relevant Conditions Problem Concern Entry - https://art-decor.org/ad/#/elgaimpf-/rules/templates/1.2.40.0.34.6.0.11.3.8/2023-03-31T12:18:19
            //act/id 
              // Mapping Recommend CRE: //act/id -> Condition.identifier  CDA IG explicitly states the act/id MUST differ from observation/id, so both have meaning; keeps the wrapper-vs-detail distinction queryable
            
            //act.reference[templateId/@root = '1.2.40.0.34.6.0.11.3.14'] (External Document Entry)
              // Mapping Recommend CRE: use the same logic as for Immunization and ImmunizationRecommendation and map External Document Entry id, code -> Condition.identifier
        

        //Template: Immunization-Relevant Conditions Problem Entry - https://art-decor.org/ad/#/elgaimpf-/rules/templates/1.2.40.0.34.6.0.11.3.9/2023-03-30T08:46:35
            
            // observation[hl7:templateId/@root='1.2.40.0.34.6.0.11.9.1']/text (Narrative Text Reference)
              //Mapping Recommend CRE: Map to Condition.text.div 
        
            //observation/value/originalText/reference (Textinhalt, der codiert wurde.)
              //Mapping Recommend CRE: Condition.code.text




    // 2. Check the mapping of all Condition.identifier 
        // Three CDA elements all land on Condition.identifier:
        //   - act/id                  (Problem Concern Entry) --> do not map (todo confirm with AG)
        //   - observation/id          (Problem Entry)  --> identifier.use 
        //   - externalDocument/id     (source CDA the entry originated from) --> identifier.use = #secondary
  //--------------------------------------- 

  //act/author -> Condition.recorder
  cda_act.author as cda_author then {
    // act/author/time -> Condition.recordedDate
    cda_author.time where ($this.nullFlavor.exists().not()) -> fhir_condition.recordedDate;

    //act/author -> Condition.recorder
    cda_author -> 
      fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('PractitionerRole') as fhir_practitionerRole,
      fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_practitionerRole_id),
      fhir_condition.recorder = create('Reference') as fhir_condition_recorder,
      fhir_condition_recorder.reference = append('urn:uuid:', fhir_practitionerRole_id),
      fhir_condition_recorder.type = 'PractitionerRole' then CdaAuthorToFhirPractitionerRole(cda_author, fhir_practitionerRole, fhir_bundle);
  };

  // ToDo
  // check mapping it leads to a faulty .py output after combiling. 
  //act/reference/externalDocument[templateId/@root='1.2.40.0.34.6.0.11.3.14 '] -> Condition.identifier 
  cda_act.reference as cda_act_reference where ($this.externalDocument.templateId.where(root='1.2.40.0.34.6.0.11.3.14')) then {
    cda_act_reference.externalDocument as cda_act_reference_externalDocument then {
      cda_act_reference_externalDocument.id as cda_act_reference_externalDocument_id -> 
        fhir_condition.identifier as fhir_condition_identifier,
        fhir_condition_identifier.use = 'secondary' then {
          cda_act_reference_externalDocument_id then II(cda_act_reference_externalDocument_id, fhir_condition_identifier);
          cda_act_reference_externalDocument.code -> fhir_condition_identifier.type;
        };
    };
  };



  //act.entryRelationship[templateId/@root='1.2.40.0.34.6.0.11.3.9'] -> Condition 
  cda_act.entryRelationship as cda_act_entryRelationship then {
    cda_act_entryRelationship.observation as cda_observation then {

      // observation/id -> Condition.identifier
      cda_observation.id -> fhir_condition.identifier; 
        
      cda_observation.effectiveTime as cda_observation_effectiveTime then {
        // observation/effectiveTime/low -> Condition.onsetDateTime
        cda_observation_effectiveTime.low as cda_observation_effectiveTime_low where ($this.nullFlavor.exists().not()) -> 
          fhir_condition.onset = create('dateTime') as fhir_condition_onset then 
          TSDate(cda_observation_effectiveTime_low, fhir_condition_onset);
        
        //observation/effectiveTime/high -> Condition.abatementDateTime
        cda_observation_effectiveTime.high as cda_observation_effectiveTime_high where $this.exists() ->
          fhir_condition.abatementDateTime = create('dateTime') as fhir_condition_abatementDateTime,

          // general assumption to set Condition.status to 'inactive' in case of an existing effectiveTime/high, since this indicates that the condition is not ongoing anymore
          fhir_condition.clinicalStatus as fhir_condition_clinicalStatus,
          fhir_condition_clinicalStatus.coding as fhir_condition_clinicalStatus_coding,
          fhir_condition_clinicalStatus_coding.system = 'http://terminology.hl7.org/CodeSystem/condition-clinical',
          fhir_condition_clinicalStatus_coding.code = 'inactive' then 
          TSDate(cda_observation_effectiveTime_high, fhir_condition_abatementDateTime);
      };

      // observation/value -> Condition.code
      cda_observation.value -> fhir_condition.code;
      
      // Participant Body - Data Enterer (1.2.40.0.34.6.0.11.9.47) -> Provenance.agent & Participant Body - Verifier (1.2.40.0.34.6.0.11.9.44) -> Provenance.agent
      // Check if observation/participant[@typeCode!='AUT'] (using template id) 
      cda_observation.participant as cda_participant where ($this.templateId.root  != '1.2.40.0.34.6.0.11.9.46') ->
        fhir_bundle.entry as fhir_bundle_entry,
        fhir_bundle_entry.resource = create('Provenance') as fhir_provenance,
        fhir_provenance.id = uuid() as fhir_provenance_id,
        fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_provenance_id),
        fhir_condition.id as fhir_condition_id,
        fhir_provenance.target = create('Reference') as fhir_provenance_target_reference,
        fhir_provenance_target_reference.reference = append('urn:uuid:', fhir_condition_id),
        fhir_provenance_target_reference.type = 'Condition' then CdaParticipantToFhirProvenance(cda_participant, fhir_provenance, fhir_bundle);

      //ToDo
      // Refactor using the narrativetext group
      // observation/entryRelationship (Comment Entry) -> Condition.note.text
      cda_observation.entryRelationship as cda_observation_entryRelationship where ($this.act.templateId.where(root='1.2.40.0.34.6.0.11.3.17')) then {
        // observation/entryRelationship/act
        cda_observation_entryRelationship.act as cda_act then {
          // observation/entryRelationship/act/text
          cda_act.text as cda_act_text then {
            // observation/entryRelationship/act/text/reference
            cda_act_text.reference as cda_act_text_reference then {
              cda_section.text as cda_section_text then {
                // observation/entryRelationship/act/text/reference/@value -> ImmunizationRecommendation.recommendation.description
                cda_act_text_reference.value as cda_act_text_reference_value -> 
                  // Create Narrative (same datatype as in Composition.section.text)
                  create('Narrative') as fhir_narrative, 
                  // section/text -> Narrative.div
                  fhir_narrative.div = cda_section_text as fhir_narrative_div,
                  
                  // Create string
                  create('string') as fhir_string,
                  // Convert test_div to a FHIR string
                  fhir_string = (fhir_narrative_div),

                  // Create substring from the ID (identified by cda_act_text_reference_value) till the end of fhir_string
                  create('string') as fhir_substring_01,
                  // cda_act_text_reference_value.substring(1) = removing '#' from reference/@value (e.g. '#commentRef-1' becomes 'commentRef-1')
                  // fhir_string.indexOf(cda_act_text_reference_value.substring(1)) = the position of the ID within section/text
                  fhir_substring_01 = (fhir_string.substring(fhir_string.indexOf(cda_act_text_reference_value.substring(1)))),

                  // Create a substring from the first occurrence of > character till the end of fhir_substring_01
                  create('string') as fhir_substring_02,
                  fhir_substring_02 = (fhir_substring_01.substring(fhir_substring_01.indexOf('>') + 1)),

                  // Create a substring from the start till the first occurrence of < character
                  fhir_condition.note as fhir_condition_note,
                  fhir_condition_note.text = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')));
              };
            };
          };
        };
      };
    };
  };
}

// _________________________ Template Type not specified  ___________________

group CdaParticipantToFhirProvenance(source cda_participant: CdaParticipant2, target fhir_provenance: FhirProvenance, target fhir_bundle: FhirBundle){
  // participant/time -> Provenance.occurredDateTime
  cda_participant.time as cda_participant_time -> 
    fhir_provenance.occurred = create('dateTime') as fhir_provenance_occurred then 
      TSDateTime(cda_participant_time, fhir_provenance_occurred) "CdaParticipantTimeToFhirProvenanceOccurred";

  // Provenance.recorded
  cda_participant -> 
    fhir_provenance.recorded as fhir_provenance_recorded,
    fhir_provenance_recorded.extension as fhir_provenance_recorded_extension,
    fhir_provenance_recorded_extension.url = 'http://hl7.org/fhir/StructureDefinition/data-absent-reason',
    fhir_provenance_recorded_extension.value = create('code') as fhir_provenance_recorded_extension_value,
    fhir_provenance_recorded_extension_value.value = 'unknown';

  // participant/participantRole -> Provenance.agent
  cda_participant.participantRole as cda_participant_role -> fhir_provenance.agent as fhir_provenance_agent then {
    // substanceAdministration/participant (Participant Body - Transcriber = Nachtragende Person (Datenverarbeitende Person))
    cda_participant where ($this.templateId.where(root='1.2.40.0.34.6.0.11.9.14')) -> 
      fhir_provenance_agent.type as fhir_provenance_agent_type,
      fhir_provenance_agent_type.coding as fhir_provenance_agent_type_coding,
      fhir_provenance_agent_type_coding.system = 'http://terminology.hl7.org/CodeSystem/provenance-participant-type',
      fhir_provenance_agent_type_coding.code = 'enterer',
      fhir_provenance_agent.role as fhir_provenance_agent_role,
      fhir_provenance_agent_role.coding as fhir_provenance_agent_role_coding,
      fhir_provenance_agent_role_coding.system = 'http://terminology.hl7.org/CodeSystem/v3-ParticipationType',
      fhir_provenance_agent_role_coding.code = 'TRANS';

    // substanceAdministration/participant (Participant Body - Verifier = Korrigierende Person (Datenverarbeitende Person))
    cda_participant where ($this.templateId.where(root='1.2.40.0.34.6.0.11.9.44')) -> 
      fhir_provenance_agent.type as fhir_provenance_agent_type,
      fhir_provenance_agent_type.coding as fhir_provenance_agent_type_coding,
      fhir_provenance_agent_type_coding.system = 'http://terminology.hl7.org/CodeSystem/provenance-participant-type',
      fhir_provenance_agent_type_coding.code = 'verifier';

    // substanceAdministration/participant (Participant Body - Data Enterer = "Eintragende Person": Die dokumentierende Person (z.B. Medizinische Dokumentationsassistenz, Schreibkraft))
    cda_participant where ($this.templateId.where(root='1.2.40.0.34.6.0.11.9.47')) -> 
      fhir_provenance_agent.type as fhir_provenance_agent_type,
      fhir_provenance_agent_type.coding as fhir_provenance_agent_type_coding,
      fhir_provenance_agent_type_coding.system = 'http://terminology.hl7.org/CodeSystem/provenance-participant-type',
      fhir_provenance_agent_type_coding.code = 'enterer',
      fhir_provenance_agent.role as fhir_provenance_agent_role,
      fhir_provenance_agent_role.coding as fhir_provenance_agent_role_coding,
      fhir_provenance_agent_role_coding.system = 'http://terminology.hl7.org/CodeSystem/v3-ParticipationType',
      fhir_provenance_agent_role_coding.code = 'ENT';

    // participantRole -> PractitionerRole
    cda_participant_role where ($this.playingEntity.exists()) -> 
      fhir_bundle.entry as fhir_bundle_entry_01,
      fhir_bundle_entry_01.resource = create('PractitionerRole') as fhir_practitionerRole,
      fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
      fhir_bundle_entry_01.fullUrl = append('urn:uuid:', fhir_practitionerRole_id),
      fhir_provenance_agent.who = create('Reference') as fhir_provenance_agent_who_reference,
      fhir_provenance_agent_who_reference.reference = append('urn:uuid:', fhir_practitionerRole_id),
      fhir_provenance_agent_who_reference.type = 'PractitionerRole',
      fhir_bundle.entry as fhir_bundle_entry_02,
      fhir_bundle_entry_02.resource = create('Practitioner') as fhir_practitioner,
      fhir_practitioner.id = uuid() as fhir_practitioner_id,
      fhir_bundle_entry_02.fullUrl = append('urn:uuid:', fhir_practitioner_id),
      fhir_practitionerRole.practitioner = create('Reference') as fhir_practitionerRole_practitioner_reference,
      fhir_practitionerRole_practitioner_reference.reference = append('urn:uuid:', fhir_practitioner_id),
      fhir_practitionerRole_practitioner_reference.type = 'Practitioner' then {
        // participantRole/id ->  Practitioner.identifier
        cda_participant_role.id where ($this.nullFlavor.exists().not()) -> fhir_practitioner.identifier;
        
        // participantRole/addr -> Practitioner.address
        cda_participant_role.addr -> fhir_practitioner.address;

        // participantRole/telecom -> Practitioner.telecom
        cda_participant_role.telecom -> fhir_practitioner.telecom;
       
        // participantRole/playingEntity -> Practitioner.name
        cda_participant_role.playingEntity as cda_participant_role_playingEntity then {
          // participantRole/playingEntity/name -> Practitioner.name
          cda_participant_role_playingEntity.name -> fhir_practitioner.name;
        };
        
        // participantRole/scopingEntity -> PractitionerRole.organization 
        cda_participant_role.scopingEntity as cda_participant_role_scoping_entity then {
          cda_participant_role_scoping_entity.desc as cda_participant_role_scoping_entity_desc ->
            fhir_practitionerRole.organization = create('Reference') as fhir_practitionerRole_organization_reference,
            fhir_practitionerRole_organization_reference.display = (cda_participant_role_scoping_entity_desc.xmlText);
        };
      };
    
    // participantRole -> Device
    cda_participant_role where ($this.playingDevice.exists()) ->
      // create Device
      fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('Device') as fhir_device,
      fhir_device.id = uuid() as fhir_device_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_device_id),
      // link Device to Provenance
      fhir_provenance_agent.who = create('Reference') as fhir_provenance_agent_who_reference,
      fhir_provenance_agent_who_reference.reference = append('urn:uuid:', fhir_device_id),
      fhir_provenance_agent_who_reference.type = 'Device' then {
        // participantRole/id ->  Device.identifier
        cda_participant_role.id where ($this.nullFlavor.exists().not()) -> fhir_device.identifier;
        
        // participantRole/telecom -> Device.contact
        cda_participant_role.telecom -> fhir_device.contact;

        // participantRole/playingDevice -> Device 
        cda_participant_role.playingDevice as cda_participant_role_playingDevice then {
          // participantRole/playingDevice/manufacturerModelName -> Device.name
          cda_participant_role_playingDevice.manufacturerModelName as cda_manufacturerModelName ->
            fhir_device.deviceName as fhir_device_deviceName,
            fhir_device_deviceName.name = (cda_manufacturerModelName.xmlText),
            fhir_device_deviceName.type = 'model-name';
          // participantRole/playingDevice/softwareName -> Device.version
          cda_participant_role_playingDevice.softwareName as cda_softwareName ->
            fhir_device.version as fhir_device_version,
            fhir_device_version.value = (cda_softwareName.xmlText);
        }

        cda_participant_role where ($this.addr.exists() or $this.scopingEntity.exists()) ->
          // create Organization
          fhir_bundle.entry as fhir_bundle_entry,
          fhir_bundle_entry.resource = create('Organization') as fhir_organization,
          fhir_organization.id = uuid() as fhir_organization_id,
          fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_organization_id),
          // link Organization to Device
          fhir_device.owner = create('Reference') as fhir_device_owner_reference,
          fhir_device_owner_reference.reference = append('urn:uuid:', fhir_organization_id),
          fhir_device_owner_reference.type = 'Organization' then {
            // participantRole/addr -> Organization.address
            cda_participant_role.addr -> fhir_organization.address;
                  
            // participantRole/scopingEntity -> PractitionerRole.organization 
            cda_participant_role.scopingEntity as cda_participant_role_scoping_entity then {
              cda_participant_role_scoping_entity.desc as cda_participant_role_scoping_entity_desc -> 
                fhir_organization.name = (cda_participant_role_scoping_entity_desc.xmlText);
            };
            // set data-absent-reason in case no organization name is present
            cda_participant_role where ($this.scopingEntity.exists().not()) ->
              fhir_organization.name as fhir_organization_name,
              fhir_organization_name.extension as fhir_organization_name_extension,
              fhir_organization_name_extension.url = 'http://hl7.org/fhir/StructureDefinition/data-absent-reason',
              fhir_organization_name_extension.value = create('code') as fhir_organization_name_extension_value,
              fhir_organization_name_extension_value.value = 'unknown';
          };
      };
  };
}

group CdaPerformerToFhirProvenance(source cda_performer: CdaPerformer2, target fhir_provenance: FhirProvenance, target fhir_practitionerRole: FhirPractitionerRole, target fhir_bundle: FhirBundle){
  // performer/time -> Provenance.occurredDateTime
  cda_performer.time as cda_participant_time -> 
    fhir_provenance.occurred = create('dateTime') as fhir_provenance_occurred then 
      TSDateTime(cda_participant_time, fhir_provenance_occurred) "CdaPerformerTimeToFhirProvenanceOccurred";

  // Provenance.recorded
  cda_participant -> 
    fhir_provenance.recorded as fhir_provenance_recorded,
    fhir_provenance_recorded.extension as fhir_provenance_recorded_extension,
    fhir_provenance_recorded_extension.url = 'http://hl7.org/fhir/StructureDefinition/data-absent-reason',
    fhir_provenance_recorded_extension.value = create('code') as fhir_provenance_recorded_extension_value,
    fhir_provenance_recorded_extension_value.value = 'unknown';

  // performer/assignedEntity -> PractitionerRole
  cda_performer.assignedEntity as cda_performer_assignedEntity ->
    fhir_provenance.agent as fhir_provenance_agent,
    fhir_provenance_agent.type as fhir_provenance_agent_type,
    fhir_provenance_agent_type.coding as fhir_provenance_agent_type_coding,
    fhir_provenance_agent_type_coding.system = 'http://terminology.hl7.org/CodeSystem/provenance-participant-type',
    fhir_provenance_agent_type_coding.code = 'performer',
    fhir_practitionerRole.id as fhir_practitionerRole_id,
    fhir_provenance_agent.who = create('Reference') as fhir_provenance_agent_who_reference,
    fhir_provenance_agent_who_reference.reference = append('urn:uuid:', fhir_practitionerRole_id),
    fhir_provenance_agent_who_reference.type = 'PractitionerRole' then 
      CdaAssignedEntityToFhirPractitionerRole(cda_performer_assignedEntity, fhir_practitionerRole, fhir_bundle);
}

group CdaAuthorPersonToFhirProvenance(source cda_author: CdaAuthor, target fhir_provenance: FhirProvenance, target fhir_practitionerRole: FhirPractitionerRole, target fhir_bundle: FhirBundle){
  // author/time -> Provenance.occurredDateTime
  // see CdaAuthorToFhirPractitionerAndPractitionerRole which is also used for ClinicalDocument/author: https://github.com/HL7Austria/CDA2FHIR/issues/159
  cda_author.time as cda_participant_time where ($this.nullFlavor.exists().not()) -> 
    fhir_provenance.occurred = create('dateTime') as fhir_provenance_occurred then 
      TSDateTime(cda_participant_time, fhir_provenance_occurred) "CdaPerformerTimeToFhirProvenanceOccurred";

  // Provenance.recorded
  cda_author -> 
    fhir_provenance.recorded as fhir_provenance_recorded,
    fhir_provenance_recorded.extension as fhir_provenance_recorded_extension,
    fhir_provenance_recorded_extension.url = 'http://hl7.org/fhir/StructureDefinition/data-absent-reason',
    fhir_provenance_recorded_extension.value = create('code') as fhir_provenance_recorded_extension_value,
    fhir_provenance_recorded_extension_value.value = 'unknown';

  // author/assignedEntity -> PractitionerRole
  cda_author ->
    fhir_provenance.agent as fhir_provenance_agent,
    fhir_provenance_agent.type as fhir_provenance_agent_type,
    fhir_provenance_agent_type.coding as fhir_provenance_agent_type_coding,
    fhir_provenance_agent_type_coding.system = 'http://terminology.hl7.org/CodeSystem/provenance-participant-type',
    fhir_provenance_agent_type_coding.code = 'author',
    fhir_practitionerRole.id as fhir_practitionerRole_id,
    fhir_provenance_agent.who = create('Reference') as fhir_provenance_agent_who_reference,
    fhir_provenance_agent_who_reference.reference = append('urn:uuid:', fhir_practitionerRole_id),
    fhir_provenance_agent_who_reference.type = 'PractitionerRole' then 
      CdaAuthorToFhirPractitionerRole(cda_author, fhir_practitionerRole, fhir_bundle);
}

group CdaAuthorDeviceToFhirProvenance(source cda_author: CdaAuthor, target fhir_provenance: FhirProvenance, target fhir_bundle: FhirBundle){
  // author/time -> Provenance.occurredDateTime
  // see CdaAuthorToFhirPractitionerAndPractitionerRole which is also used for ClinicalDocument/author: https://github.com/HL7Austria/CDA2FHIR/issues/159
  cda_author.time as cda_participant_time where ($this.nullFlavor.exists().not()) -> 
    fhir_provenance.occurred = create('dateTime') as fhir_provenance_occurred then 
      TSDateTime(cda_participant_time, fhir_provenance_occurred) "CdaPerformerTimeToFhirProvenanceOccurred";

  // Provenance.recorded
  cda_author -> 
    fhir_provenance.recorded as fhir_provenance_recorded,
    fhir_provenance_recorded.extension as fhir_provenance_recorded_extension,
    fhir_provenance_recorded_extension.url = 'http://hl7.org/fhir/StructureDefinition/data-absent-reason',
    fhir_provenance_recorded_extension.value = create('code') as fhir_provenance_recorded_extension_value,
    fhir_provenance_recorded_extension_value.value = 'unknown';

  // author/assignedEntity -> Device
  cda_author ->
    fhir_provenance.agent as fhir_provenance_agent,
    fhir_provenance_agent.type as fhir_provenance_agent_type,
    fhir_provenance_agent_type.coding as fhir_provenance_agent_type_coding,
    fhir_provenance_agent_type_coding.system = 'http://terminology.hl7.org/CodeSystem/provenance-participant-type',
    fhir_provenance_agent_type_coding.code = 'author',
    fhir_bundle.entry as fhir_bundle_entry,
    fhir_bundle_entry.resource = create('Device') as fhir_device,
    fhir_device.id = uuid() as fhir_device_id,
    fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_device_id),
    fhir_provenance_agent.who = create('Reference') as fhir_provenance_agent_who_reference,
    fhir_provenance_agent_who_reference.reference = append('urn:uuid:', fhir_device_id),
    fhir_provenance_agent_who_reference.type = 'Device' then 
      CdaAuthorToFhirDevice(cda_author, fhir_device, fhir_bundle);
}